WITH valid_products AS (SELECT * FROM products WHERE launch_date > '2024-03-07'), agg AS (SELECT CASE WHEN price >= 1320 THEN 'high' WHEN price >= 310 THEN 'mid' ELSE 'low' END price_bucket, SUM(cost) total_cost, COUNT(*) num_products FROM valid_products GROUP BY CASE WHEN price >= 1320 THEN 'high' WHEN price >= 310 THEN 'mid' ELSE 'low' END) SELECT price_bucket, total_cost, num_products FROM agg WHERE total_cost < 2800 ORDER BY total_cost DESC
